<?php require_once 'bootstrap.php';$u=require_admin();$msg='';$defaultScope=user_club_sic($u['sic_id']);if($defaultScope&&!acl_can($u['sic_id'],'finance','READ',$defaultScope,$u['sic_id'])&&!has_role($u['sic_id'],'SUPERADMIN')){http_response_code(403);exit('Accesso non autorizzato.');}if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$dir=$_POST['direction']??'IN';$amt=(float)($_POST['amount']??0);$cat=trim($_POST['category']??'OTHER');$desc=trim($_POST['description']??'');$scope=trim($_POST['scope_sic_id']??'')?:($defaultScope?:'');if($scope&&!acl_can($u['sic_id'],'finance','MANAGE',$scope,$u['sic_id'])&&!has_role($u['sic_id'],'SUPERADMIN')){http_response_code(403);exit('Scope non autorizzato.');}if($amt>0){$acc=db()->prepare('SELECT sic_id FROM treasury_accounts WHERE owner_scope_sic_id=? LIMIT 1');$acc->execute([$scope]);$account=$acc->fetchColumn();if(!$account){$account=sic_id();db()->prepare('INSERT INTO treasury_accounts(sic_id,owner_scope_sic_id,currency,account_type,label) VALUES(?,?,"EUR","OPERATING","Tesoreria")')->execute([$account,$scope]);}db()->prepare('INSERT INTO treasury_transactions(sic_id,account_sic_id,direction,amount,category,description,approved_by_sic_id) VALUES(?,?,?,?,?,?,?)')->execute([sic_id(),$account,$dir,$amt,$cat,$desc,$u['sic_id']]);if($dir==='IN'&&$cat==='CLUB_MEMBERSHIP'&&!empty($_POST['member_sic_id'])){drx_post($_POST['member_sic_id'],null,$amt*drx_setting('membership_eur_to_drx',1),'CLUB_MEMBERSHIP',false,'membership:'.$_POST['member_sic_id'].':'.date('Ym').':'.$amt,null,['eur'=>$amt]);}$msg='Movimento registrato.';}}$bal=(float)db()->query("SELECT COALESCE(SUM(CASE WHEN direction='IN' THEN amount ELSE -amount END),0) FROM treasury_transactions")->fetchColumn();$moves=db()->query('SELECT tt.*,ta.label FROM treasury_transactions tt JOIN treasury_accounts ta ON ta.sic_id=tt.account_sic_id ORDER BY tt.created_at DESC LIMIT 50')->fetchAll();$pageTitle='Tesoreria';require '_header.php';?><section class="section-head"><div><span class="eyebrow">Finance OS</span><h1>Tesoreria digitale</h1><p>Entrate, quote, donazioni, spese e rimborsi con SIC-ID e audit.</p></div></section><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><section class="metric-grid"><div class="metric"><b>€ <?=number_format($bal,2,',','.')?></b><span>Saldo registrato</span></div><div class="metric"><b><?=count($moves)?></b><span>Ultimi movimenti</span></div></section><section class="card"><h2>Registra movimento</h2><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><label>Scope SIC-ID<input name="scope_sic_id" placeholder="Club / associazione"></label><label>Direzione<select name="direction"><option value="IN">Entrata</option><option value="OUT">Uscita</option></select></label><label>Importo €<input type="number" step="0.01" name="amount" required></label><label>Categoria<select name="category"><option>CLUB_MEMBERSHIP</option><option>DONATION</option><option>EVENT</option><option>GRANT</option><option>MATERIALS</option><option>TRAVEL</option><option>REFUND</option><option>OTHER</option></select></label><label>SIC-ID membro (solo quota)<input name="member_sic_id"></label><label>Descrizione<input name="description"></label><button class="btn primary">Registra</button></form></section><section class="card"><h2>Movimenti</h2><?php foreach($moves as $m):?><div class="leader-row"><b><?=h($m['direction'])?></b><span><?=h($m['category'])?> · <?=h($m['description'])?></span><em>€ <?=number_format((float)$m['amount'],2,',','.')?></em></div><?php endforeach;?></section><?php require '_footer.php';?>